#!/bin/sh
set -eu
base=$(CDPATH='' cd "$(dirname "$0")/.." && pwd)
: "${MUPDF:?Set MUPDF to MuPDF sources}"
: "${FIXTURES:?Set FIXTURES to generated fixture directory}"
: "${TEST_WORK:?Set TEST_WORK to a fresh temporary directory}"
export LUMEN_UI_FONT="$base/fonts/DroidSansFallbackFull.ttf"
mkdir -p "$TEST_WORK/data"
cp -R "$base/catalogs" "$TEST_WORK/catalogs"
for name in system/library system/engine system/device system/connect system/amazon system/qrcodegen apps/discover system/network apps/apps apps/calc apps/scratch apps/puzzles apps/newspaper apps/press apps/learning vendor/astronomy system/services system/i18n system/app_runtime system/text_edit system/text_input system/preferences system/unicode system/fonts apps/registry; do
  clang -DLUMEN_HOST -g -fsanitize=address,undefined -I"$MUPDF/include" -c "$base/src/$name.c" -o "$TEST_WORK/$(basename "$name").o"
done
clang -DLUMEN_HOST -g -fsanitize=address,undefined -I"$MUPDF/include" -c "$base/tests/test_core.c" -o "$TEST_WORK/test.o"
clang++ -fsanitize=address,undefined "$TEST_WORK/test.o" "$TEST_WORK/library.o" "$TEST_WORK/engine.o" "$TEST_WORK/amazon.o" "$TEST_WORK/apps.o" "$TEST_WORK/calc.o" "$TEST_WORK/scratch.o" "$TEST_WORK/puzzles.o" "$TEST_WORK/newspaper.o" "$TEST_WORK/press.o" "$TEST_WORK/learning.o" "$TEST_WORK/astronomy.o" "$TEST_WORK/services.o" "$TEST_WORK/device.o" "$TEST_WORK/connect.o" "$TEST_WORK/qrcodegen.o" "$TEST_WORK/discover.o" "$TEST_WORK/network.o" "$TEST_WORK/i18n.o" "$TEST_WORK/app_runtime.o" "$TEST_WORK/unicode.o" "$TEST_WORK/fonts.o" "$TEST_WORK/registry.o" "$TEST_WORK/text_edit.o" "$TEST_WORK/text_input.o" "$TEST_WORK/preferences.o" "$MUPDF/build/lumen-host/libmupdf.a" "$MUPDF/build/lumen-host/libmupdf-third.a" -lm -lpthread -o "$TEST_WORK/test-core"
"$TEST_WORK/test-core" "$FIXTURES" "$TEST_WORK/data"
clang -DLUMEN_HOST -g -fsanitize=address,undefined -I"$MUPDF/include" -c "$base/tests/test_ui.c" -o "$TEST_WORK/ui-test.o"
clang++ -fsanitize=address,undefined "$TEST_WORK/ui-test.o" "$TEST_WORK/apps.o" "$TEST_WORK/calc.o" "$TEST_WORK/scratch.o" "$TEST_WORK/puzzles.o" "$TEST_WORK/newspaper.o" "$TEST_WORK/press.o" "$TEST_WORK/learning.o" "$TEST_WORK/astronomy.o" "$TEST_WORK/services.o" "$TEST_WORK/library.o" "$TEST_WORK/engine.o" "$TEST_WORK/device.o" "$TEST_WORK/connect.o" "$TEST_WORK/amazon.o" "$TEST_WORK/qrcodegen.o" "$TEST_WORK/discover.o" "$TEST_WORK/network.o" "$TEST_WORK/i18n.o" "$TEST_WORK/app_runtime.o" "$TEST_WORK/unicode.o" "$TEST_WORK/fonts.o" "$TEST_WORK/registry.o" "$TEST_WORK/text_edit.o" "$TEST_WORK/text_input.o" "$TEST_WORK/preferences.o" "$MUPDF/build/lumen-host/libmupdf.a" "$MUPDF/build/lumen-host/libmupdf-third.a" -lm -lpthread -o "$TEST_WORK/test-ui"
mkdir -p "$TEST_WORK/ui-data"
"$TEST_WORK/test-ui" "$FIXTURES" "$TEST_WORK/ui-data"
clang -DLUMEN_HOST -g -fsanitize=address,undefined -I"$MUPDF/include" -c "$base/tests/test_sources.c" -o "$TEST_WORK/sources-test.o"
clang++ -fsanitize=address,undefined "$TEST_WORK/sources-test.o" "$TEST_WORK/discover.o" "$TEST_WORK/library.o" "$TEST_WORK/engine.o" "$TEST_WORK/amazon.o" "$TEST_WORK/apps.o" "$TEST_WORK/calc.o" "$TEST_WORK/scratch.o" "$TEST_WORK/puzzles.o" "$TEST_WORK/newspaper.o" "$TEST_WORK/press.o" "$TEST_WORK/learning.o" "$TEST_WORK/astronomy.o" "$TEST_WORK/services.o" "$TEST_WORK/device.o" "$TEST_WORK/connect.o" "$TEST_WORK/qrcodegen.o" "$TEST_WORK/network.o" "$TEST_WORK/i18n.o" "$TEST_WORK/app_runtime.o" "$TEST_WORK/unicode.o" "$TEST_WORK/fonts.o" "$TEST_WORK/registry.o" "$TEST_WORK/text_edit.o" "$TEST_WORK/text_input.o" "$TEST_WORK/preferences.o" "$MUPDF/build/lumen-host/libmupdf.a" "$MUPDF/build/lumen-host/libmupdf-third.a" -lm -lpthread -o "$TEST_WORK/test-sources"
"$TEST_WORK/test-sources" "$base/tests/sources/archive-search.xml" "$base/tests/sources/archive-files.xml"
clang -DLUMEN_HOST -g -fsanitize=address,undefined "$base/tests/test_network.c" "$TEST_WORK/network.o" "$base/tests/i18n_stub.c" -o "$TEST_WORK/test-network"
"$TEST_WORK/test-network"
clang -g -fsanitize=address,undefined "$base/tests/test_refresh.c" -o "$TEST_WORK/test-refresh"
"$TEST_WORK/test-refresh"
clang -DLUMEN_HOST -g -fsanitize=address,undefined -I"$MUPDF/include" -c "$base/tests/test_reader_features.c" -o "$TEST_WORK/reader-features.o"
clang++ -fsanitize=address,undefined "$TEST_WORK/reader-features.o" "$TEST_WORK/engine.o" "$TEST_WORK/library.o" "$TEST_WORK/amazon.o" "$TEST_WORK/apps.o" "$TEST_WORK/calc.o" "$TEST_WORK/scratch.o" "$TEST_WORK/puzzles.o" "$TEST_WORK/newspaper.o" "$TEST_WORK/press.o" "$TEST_WORK/learning.o" "$TEST_WORK/astronomy.o" "$TEST_WORK/services.o" "$TEST_WORK/device.o" "$TEST_WORK/connect.o" "$TEST_WORK/qrcodegen.o" "$TEST_WORK/discover.o" "$TEST_WORK/network.o" "$TEST_WORK/i18n.o" "$TEST_WORK/app_runtime.o" "$TEST_WORK/unicode.o" "$TEST_WORK/fonts.o" "$TEST_WORK/registry.o" "$TEST_WORK/text_edit.o" "$TEST_WORK/text_input.o" "$TEST_WORK/preferences.o" "$MUPDF/build/lumen-host/libmupdf.a" "$MUPDF/build/lumen-host/libmupdf-third.a" -lm -lpthread -o "$TEST_WORK/test-reader-features"
"$TEST_WORK/test-reader-features" "$FIXTURES/LUMEN Lesetest.epub"
clang -g -fsanitize=address,undefined "$base/tests/test_apps.c" "$TEST_WORK/apps.o" -o "$TEST_WORK/test-apps"
"$TEST_WORK/test-apps"
clang -DLUMEN_HOST -g -fsanitize=address,undefined "$base/tests/test_tools.c" "$TEST_WORK/calc.o" "$TEST_WORK/scratch.o" "$TEST_WORK/puzzles.o" "$TEST_WORK/newspaper.o" "$TEST_WORK/press.o" "$TEST_WORK/learning.o" "$TEST_WORK/astronomy.o" "$TEST_WORK/services.o" "$TEST_WORK/library.o" "$TEST_WORK/engine.o" "$TEST_WORK/amazon.o" "$MUPDF/build/lumen-host/libmupdf.a" "$MUPDF/build/lumen-host/libmupdf-third.a" -lm -lstdc++ -o "$TEST_WORK/test-tools"
"$TEST_WORK/test-tools"
clang -DLUMEN_HOST -g -fsanitize=address,undefined -I"$MUPDF/include" -c "$base/tests/test_tools_ui.c" -o "$TEST_WORK/tools-ui-test.o"
clang++ -fsanitize=address,undefined "$TEST_WORK/tools-ui-test.o" "$TEST_WORK/apps.o" "$TEST_WORK/calc.o" "$TEST_WORK/scratch.o" "$TEST_WORK/puzzles.o" "$TEST_WORK/newspaper.o" "$TEST_WORK/press.o" "$TEST_WORK/learning.o" "$TEST_WORK/astronomy.o" "$TEST_WORK/services.o" "$TEST_WORK/library.o" "$TEST_WORK/engine.o" "$TEST_WORK/device.o" "$TEST_WORK/connect.o" "$TEST_WORK/amazon.o" "$TEST_WORK/qrcodegen.o" "$TEST_WORK/discover.o" "$TEST_WORK/network.o" "$TEST_WORK/i18n.o" "$TEST_WORK/app_runtime.o" "$TEST_WORK/unicode.o" "$TEST_WORK/fonts.o" "$TEST_WORK/registry.o" "$TEST_WORK/text_edit.o" "$TEST_WORK/text_input.o" "$TEST_WORK/preferences.o" "$MUPDF/build/lumen-host/libmupdf.a" "$MUPDF/build/lumen-host/libmupdf-third.a" -lm -lpthread -o "$TEST_WORK/test-tools-ui"
mkdir -p "$TEST_WORK/tools-ui-data"
"$TEST_WORK/test-tools-ui" "$FIXTURES" "$TEST_WORK/tools-ui-data"
